+        type: "block",
+        kind,
+        path: requirePath(path, `${kind} block`, location),
+        truthy: [],
+        falsy: [],
+        location,
+      };
+      output.push(block);
+      const frame: Frame = { block, output: block.truthy, inElse: false };
+      stack.push(frame);
+      output = frame.output;
+      continue;
+    }
+
+    if (content.startsWith("/")) {
