+function scalarToString(value: unknown, path: string, location: Location): string {
+  if (value === undefined || value === null) return "";
+  switch (typeof value) {
+    case "string":
+      return value;
+    case "number":
+    case "bigint":
+    case "boolean":
+      return String(value);
+    default:
+      throw new Error(
